def compile_mjcf(facts, out):
    cm={'base':None,'minute_input_bearing':None,'intermediate_bearing':None,'rear_mast':None,'lower_sleeve_bracket':None,'upper_sleeve_bracket':None,'sleeve_thrust_washer':None,'lower_sleeve_bearing':None,'upper_sleeve_bearing':None,'minute_shaft':'minute_spin','minute_gear':'minute_spin','minute_hand':'minute_spin','intermediate_shaft':'intermediate_spin','compound_big_gear':'intermediate_spin','compound_pinion':'intermediate_spin','hour_sleeve':'hour_spin','hour_gear':'hour_spin','hour_hand':'hour_spin'}
    tree=[['base',''],['minute_input_bearing','base'],['intermediate_bearing','base'],['rear_mast','base'],['lower_sleeve_bracket','rear_mast'],['upper_sleeve_bracket','rear_mast'],['sleeve_thrust_washer','lower_sleeve_bracket'],['lower_sleeve_bearing','lower_sleeve_bracket'],['upper_sleeve_bearing','upper_sleeve_bracket'],['minute_shaft','minute_input_bearing'],['minute_gear','minute_shaft'],['minute_hand','minute_shaft'],['intermediate_shaft','intermediate_bearing'],['compound_big_gear','intermediate_shaft'],['compound_pinion','intermediate_shaft'],['hour_sleeve','lower_sleeve_bearing'],['hour_gear','hour_sleeve'],['hour_hand','hour_sleeve']]
    rel={
      ('minute_gear','compound_big_gear'):('relation/stage1_tooth_contact','fit/minute_gear/stage1_mesh/compound_big_gear/stage1_mesh','ideal external gear equality'),('compound_pinion','hour_gear'):('relation/stage2_tooth_contact','fit/hour_gear/stage2_mesh/compound_pinion/stage2_mesh','ideal external gear equality'),
      ('minute_shaft','minute_gear'):('relation/minute_gear_press_fit','fit/minute_shaft/minute_gear_seat/minute_gear/shaft_bore','measured interference press fit'),('intermediate_shaft','compound_big_gear'):('relation/compound_big_press_fit','fit/intermediate_shaft/big_gear_seat/compound_big_gear/shaft_bore','measured interference press fit'),('intermediate_shaft','compound_pinion'):('relation/compound_pinion_press_fit','fit/intermediate_shaft/pinion_seat/compound_pinion/shaft_bore','measured interference press fit'),('hour_sleeve','hour_gear'):('relation/hour_gear_press_fit','fit/hour_sleeve/hour_gear_seat/hour_gear/sleeve_bore','measured interference press fit'),('minute_shaft','minute_hand'):('relation/minute_hand_press_fit','fit/minute_shaft/minute_hand_seat/minute_hand/hub_bore','measured interference press fit'),('hour_sleeve','hour_hand'):('relation/hour_hand_press_fit','fit/hour_sleeve/hour_hand_seat/hour_hand/hub_bore','measured interference press fit'),
      ('minute_input_bearing','minute_shaft'):('relation/minute_lower_journal','fit/minute_input_bearing/journal_bore/minute_shaft/lower_journal','measured-clearance running journal represented by hinge'),('intermediate_bearing','intermediate_shaft'):('relation/intermediate_lower_journal','fit/intermediate_bearing/journal_bore/intermediate_shaft/lower_journal','measured-clearance running journal represented by hinge'),('lower_sleeve_bearing','hour_sleeve'):('relation/hour_sleeve_lower_journal','fit/lower_sleeve_bearing/journal_bore/hour_sleeve/lower_outer_journal','measured-clearance running journal represented by hinge'),('upper_sleeve_bearing','hour_sleeve'):('relation/hour_sleeve_upper_journal','fit/upper_sleeve_bearing/journal_bore/hour_sleeve/upper_outer_journal','measured-clearance running journal represented by hinge'),('minute_shaft','hour_sleeve'):('relation/independent_coaxial_handshaft_journal','fit/hour_sleeve/inner_journal/minute_shaft/sleeve_journal','measured-clearance independent coaxial journal')}
    raw=[('minute_shaft','base'),('minute_shaft','minute_input_bearing'),('minute_shaft','sleeve_thrust_washer'),('minute_shaft','lower_sleeve_bearing'),('minute_shaft','upper_sleeve_bearing'),('minute_shaft','hour_sleeve'),('minute_shaft','minute_gear'),('minute_shaft','hour_gear'),('minute_shaft','hour_hand'),('minute_shaft','minute_hand'),('minute_shaft','compound_big_gear'),('minute_shaft','lower_sleeve_bracket'),('minute_shaft','upper_sleeve_bracket'),('intermediate_shaft','base'),('intermediate_shaft','intermediate_bearing'),('intermediate_shaft','compound_big_gear'),('intermediate_shaft','compound_pinion'),('intermediate_shaft','hour_gear'),('hour_sleeve','sleeve_thrust_washer'),('hour_sleeve','lower_sleeve_bearing'),('hour_sleeve','upper_sleeve_bearing'),('hour_sleeve','hour_gear'),('hour_sleeve','hour_hand'),('hour_sleeve','minute_hand'),('hour_sleeve','minute_gear'),('hour_sleeve','compound_big_gear'),('hour_sleeve','lower_sleeve_bracket'),('hour_sleeve','upper_sleeve_bracket'),('hour_sleeve','minute_input_bearing'),('hour_sleeve','base'),('minute_gear','compound_big_gear'),('minute_gear','minute_input_bearing'),('minute_gear','sleeve_thrust_washer'),('minute_gear','lower_sleeve_bracket'),('minute_gear','lower_sleeve_bearing'),('minute_gear','base'),('minute_gear','hour_gear'),('compound_big_gear','minute_input_bearing'),('compound_big_gear','intermediate_bearing'),('compound_big_gear','sleeve_thrust_washer'),('compound_big_gear','lower_sleeve_bearing'),('compound_big_gear','lower_sleeve_bracket'),('compound_big_gear','base'),('compound_big_gear','rear_mast'),('compound_big_gear','compound_pinion'),('compound_big_gear','hour_gear'),('compound_big_gear','upper_sleeve_bearing'),('compound_big_gear','upper_sleeve_bracket'),('compound_big_gear','hour_hand'),('compound_big_gear','minute_hand'),('compound_pinion','hour_gear'),('compound_pinion','hour_hand'),('hour_gear','lower_sleeve_bracket'),('hour_gear','lower_sleeve_bearing'),('hour_gear','upper_sleeve_bracket'),('hour_gear','upper_sleeve_bearing'),('hour_gear','rear_mast'),('hour_gear','sleeve_thrust_washer'),('hour_gear','hour_hand'),('hour_gear','minute_hand'),('hour_gear','minute_input_bearing'),('hour_gear','intermediate_bearing'),('hour_gear','base'),('minute_hand','hour_hand'),('minute_hand','upper_sleeve_bearing'),('minute_hand','upper_sleeve_bracket'),('hour_hand','upper_sleeve_bracket'),('hour_hand','upper_sleeve_bearing')]
    contacts=[]; seen=[]
    for a,b in raw:
        k=tuple(sorted([a,b]))
        if k in seen: continue
        seen.append(k); rs=rel.get((a,b),rel.get((b,a))); pf='pair/'+k[0]+'/'+k[1]; nf='nearby/'+k[0]+'/'+k[1]
        if rs: action='exclude'; reason=rs[2]; src=['link/'+a,'link/'+b,rs[0]]; fids=[rs[1],pf]
        elif k==tuple(sorted(['hour_sleeve','sleeve_thrust_washer'])): action='keep'; reason='real axial thrust interface is the accessory contact function'; src=['link/'+a,'link/'+b]; fids=[pf,nf]
        else: action='exclude'; reason='measured positive separation or disjoint AABB extent: collision-proxy false-contact risk with no contact function'; src=['link/'+a,'link/'+b]; fids=[pf,nf]
        contacts.append({'pair':[a,b],'action':action,'reason':reason,'source_entity_ids':src,'fact_ids':fids})
    plan={'coordinate_map':cm,'tree_edges':tree,'closure_edges':[],'rigid_carried':[['minute_shaft','minute_gear'],['minute_shaft','minute_hand'],['intermediate_shaft','compound_big_gear'],['intermediate_shaft','compound_pinion'],['hour_sleeve','hour_gear'],['hour_sleeve','hour_hand']],'independent_coaxial':[['minute_shaft','hour_sleeve']],'transmissions':[{'name':'minute_to_compound_reduction','driving_joint':'minute_spin','driven_joint':'intermediate_spin','ratio':-0.3333333333333333},{'name':'rigid_compound_pair','coordinate':'intermediate_spin','ratio':1.0},{'name':'compound_to_hour_reduction','driving_joint':'intermediate_spin','driven_joint':'hour_spin','ratio':-0.25}],'contact_decisions':contacts,'support_ground':['base'],'support_strategy':'fixed base and fixed support frame with three bearing-supported hinge coordinates; no support patch required'}
    out.topology_plan(plan)
    for b,p in tree: out.body(b,p)
    out.joint('minute_shaft','minute_spin','hinge',(0,0,1),(0,0,5.5),'world'); out.joint('intermediate_shaft','intermediate_spin','hinge',(0,0,1),(24,0,5.5),'world'); out.joint('hour_sleeve','hour_spin','hinge',(0,0,1),(0,0,14.6),'world')
    out.joint_equality('minute_to_compound_reduction','minute_spin','intermediate_spin',-0.3333333333333333,0.0,'6 mm to 18 mm external pitch-radius mesh',['transmission/minute_to_compound_reduction','relation/stage1_tooth_contact'],['fit/minute_gear/stage1_mesh/compound_big_gear/stage1_mesh'])
    out.joint_equality('compound_to_hour_reduction','intermediate_spin','hour_spin',-0.25,0.0,'4.8 mm to 19.2 mm external pitch-radius mesh',['transmission/compound_to_hour_reduction','relation/stage2_tooth_contact'],['fit/hour_gear/stage2_mesh/compound_pinion/stage2_mesh'])
    for c in contacts:
        if c['action']=='exclude': out.exclude(c['pair'][0],c['pair'][1],c['reason'],c['source_entity_ids'],c['fact_ids'])
    ids=facts['entity_ids']
    for eid in ids:
        nodes=[]; reason='authored fact represented by emitted body, coordinate, transmission, pair decision, or immutable placement metadata'
        if eid.startswith('link/'):
            n=eid[5:]; nodes=[n]
            if cm[n]: nodes.append(cm[n])
        elif eid=='transmission/minute_to_compound_reduction': nodes=['minute_to_compound_reduction']
        elif eid=='transmission/compound_to_hour_reduction': nodes=['compound_to_hour_reduction']
        elif eid=='transmission/rigid_compound_pair': nodes=['intermediate_spin']
        out.decision(eid,'emitted' if eid.startswith('link/') else 'represented_by',nodes,reason,[eid])

